[CmdletBinding()]
param([Parameter(Mandatory=$true)][string]$ProjectPath,[switch]$BindingSmokeOnly)
$ErrorActionPreference='Stop';Set-StrictMode -Version Latest
$ProjectPath=[IO.Path]::GetFullPath($ProjectPath);$planPath=Join-Path $ProjectPath 'Research\Gate13R_48h_10pct_3Lane_Pilot_Plan.v1.json';$output=Join-Path $ProjectPath 'Research\Gate13R_48h_10pct_3Lane_Pilot_Schedule.v1.json';$receipt=Join-Path $ProjectPath 'Research\Gate13R_48h_10pct_3Lane_Pilot_Schedule_Generation.v1.json'
if($BindingSmokeOnly){Write-Output("BINDING-SMOKE-PASSED|New-Gate13R48h3LaneScheduleV1|$output");exit 0};foreach($path in @($output,$receipt)){if(Test-Path $path){throw "Create-new schedule artifact exists: $path"}}
Import-Module (Join-Path $ProjectPath 'Research\Gate13R48h3LanePreparationV1.psm1') -Force;$plan=Read-G13R48Json $planPath;$campaigns=@(Get-G13R48PilotCampaigns -ProjectPath $ProjectPath -Plan $plan);$rows=@(Get-G13R48MeasuredSchedule -Plan $plan -Campaigns $campaigns);$test=Test-G13R48Schedule $rows;if($test.passed-ne$true){throw($test.errors-join'; ')}
$campaignLane=@($rows|Group-Object campaignId,lane|ForEach-Object{[pscustomobject]@{cell=$_.Name;count=$_.Count}});$admission=@($rows|Group-Object lane,admissionPosition|ForEach-Object{[pscustomobject]@{cell=$_.Name;count=$_.Count}});$document=[ordered]@{schemaVersion=1;scheduleId='gate13r-48h-10pct-three-lane-pilot-schedule-v1';planId=[string]$plan.planId;executionDesignId=[string]$plan.executionDesignId;generatedAtUtc=[DateTime]::UtcNow.ToString('o');formalCampaign=$false;excludedFromFormalAnalysis=$true;rowCount=$rows.Count;waveCount=@($rows.wave|Sort-Object -Unique).Count;laneTotals=@($rows|Group-Object lane|ForEach-Object{[pscustomobject]@{lane=[int]$_.Name;count=$_.Count}});campaignLaneCells=$campaignLane;laneAdmissionCells=$admission;test=$test;rows=$rows};Write-G13R48CreateNewUtf8NoBomJson $output $document 40
